131	// labelPair 是标签键值对字典序比较的单元。
132	type labelPair struct {
133		Key, Value string
134	}
135	
136	func sortedPairs(labels map[string]string) []labelPair {
137		keys := sortedKeys(labels)
138		pairs := make([]labelPair, len(keys))
139		for i, k := range keys {
140			pairs[i] = labelPair{Key: k, Value: labels[k]}
141		}
142		return pairs
143	}
144	
145	func compareLabelPairs(a, b []labelPair) int {
146		n := len(a)
147		if len(b) < n {
148			n = len(b)
149		}
150		for i := 0; i < n; i++ {
151			if a[i].Key != b[i].Key {
152				return strings.Compare(a[i].Key, b[i].Key)
153			}
154			if a[i].Value != b[i].Value {
155				return strings.Compare(a[i].Value, b[i].Value)
156			}
157		}
158		switch {
159		case len(a) < len(b):
160			return -1
161		case len(a) > len(b):
162			return 1
163		}
164		return 0
165	}
166	
167	var (
168		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
169		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
170	)
171	
172	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
173	// 成功时返回非 nil 的 *BatchResult 或 *QueryResult 且错误为 nil；任何失败都返回
174	// 真正的 nil 结果与 *LineError，调用方直接比较 result == nil 即可判定失败，
175	// 无须先区分结果类型。空写入数组与无命中的查询仍是成功，结果不为 nil。
176	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
177		top, ok, lerr := decodeTopValue(line)
178		if lerr != nil {
179			return nil, lerr
180		}
181		switch ok {
182		case '[':
183			var items []json.RawMessage
184			if err := json.Unmarshal(top, &items); err != nil {
185				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
186			}
187			// 不能把 *BatchResult 直接装进 any 返回：失败时它是带类型的 nil 指针，
188			// 接口值非 nil，调用方会把失败误判为有结果。
189			batch, lerr := s.ingestItems(items)
190			if lerr != nil {
191				return nil, lerr
192			}
193			return batch, nil
194		case '{':
195			// 同上：失败时不能把带类型 nil 的 *QueryResult 装进 any。
196			query, lerr := s.queryFromObject(top)
197			if lerr != nil {
198				return nil, lerr
199			}
200			return query, nil
201		default:
202			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
203		}
204	}
205	
206	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
207	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
208	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
209		top, ok, lerr := decodeTopValue(line)
210		if lerr != nil {
211			return nil, lerr
212		}
213		if ok != '[' {
214			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
215		}
216		var items []json.RawMessage
217		if err := json.Unmarshal(top, &items); err != nil {
218			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
219		}
220		return s.ingestItems(items)
221	}
