36	func (w *failingResultWriter) Write(p []byte) (int, error) {
37		if w.deliver > 0 {
38			w.deliver--
39			w.buf.Write(p)
40			return len(p), nil
41		}
42		w.faultCalls++
43		if w.partial > 0 {
44			n := w.partial
45			if n > len(p) {
46				n = len(p)
47			}
48			w.buf.Write(p[:n])
49			return n, errResultSink
50		}
51		return 0, errResultSink
52	}
