54	// captureStderr 临时把 os.Stderr 接到管道，同步执行 fn（runIngest 不启动 goroutine，
55	// 返回前所有 stderr 写入都已完成），返回退出码与捕获到的标准错误内容。
56	func captureStderr(t *testing.T, fn func() int) (int, string) {
57		t.Helper()
58		r, w, err := os.Pipe()
59		if err != nil {
60			t.Fatalf("pipe: %v", err)
61		}
62		old := os.Stderr
63		os.Stderr = w
64		code := fn()
