251	// TestRunIngestResultWriteFailureTerminates 固定结果写出故障的全部终止语义。
252	func TestRunIngestResultWriteFailureTerminates(t *testing.T) {
253		for _, tc := range writeFaultCases() {
254			t.Run(tc.name, func(t *testing.T) {
255				// 参考运行：输出目标永不失败，取得每条结果确定的字节形态（均以 '\n' 结尾）。
256				var ref bytes.Buffer
257				runIngest(tc.newInput(), &ref)
258				records := splitRecordLines(t, ref.Bytes())
259				if len(records) != tc.records {
260					t.Fatalf("reference run produced %d records, want %d", len(records), tc.records)
261				}
262				assertTargetKind(t, tc.kind, records[tc.target-1])
263				// 用例设计自检：目标之后必须还有可产出结果的输入行，
264				// 否则无法证明“剩余输入行不再产生结果”。
265				if tc.target >= len(records) {
266					t.Fatalf("case design: target %d must leave later records, only have %d",
267						tc.target, len(records))
268				}
269	
270				sink := &failingResultWriter{deliver: tc.target - 1}
271				cut := 0
272				if tc.partial {
273					// 在目标结果的正中间截断，保证切在 JSON 内部且不会切到结尾的 '\n'。
274					cut = len(records[tc.target-1]) / 2
275					if cut < 1 || cut >= len(records[tc.target-1])-1 {
276						t.Fatalf("partial cut %d invalid for %d-byte record", cut, len(records[tc.target-1]))
277					}
278					sink.partial = cut
279				}
280	
281				code, stderr := captureStderr(t, func() int {
282					return runIngest(tc.newInput(), sink)
283				})
284	
285				// 退出码非零；底层输出错误必须发生且只发生一次：不重试当前结果，
286				// 后续行（包括末尾合法写入/查询）也不再尝试写出。
287				if code != 1 {
288					t.Fatalf("exit code = %d, want 1 when result delivery fails", code)
289				}
290				if sink.faultCalls != 1 {
291					t.Fatalf("sink faulted %d time(s), want exactly 1 (no retry, no later results)",
292						sink.faultCalls)
293				}
294	
295				// 已完整交付的只能是目标之前的记录（参考输出的严格字节前缀：顺序、内容一致，不重发）；
296				// 部分接收时再多出目标记录的前 cut 个字节，且不得包含结尾 '\n'。
297				want := bytes.Join(records[:tc.target-1], nil)
298				var fragment []byte
299				if tc.partial {
300					fragment = records[tc.target-1][:cut]
301					want = append(append(make([]byte, 0, len(want)+len(fragment)), want...), fragment...)
302				}
303				if got := sink.buf.Bytes(); !bytes.Equal(got, want) {
304					t.Fatalf("delivered stdout bytes mismatch:\n got %q\nwant %q", got, want)
305				}
306	
307				// 此前完整交付的旧记录仍可各自解析为 JSON，且与参考输出逐字节一致。
308				for i, raw := range records[:tc.target-1] {
309					var m map[string]interface{}
310					if err := json.Unmarshal(raw, &m); err != nil {
311						t.Fatalf("delivered record %d %q stopped being valid JSON: %v", i+1, raw, err)
312					}
313				}
314	
315				// 片段必须能与正常响应区分：没有行分隔符、本身不是合法 JSON，
316				// 消费者不能把它当成一条完整响应。
317				if tc.partial {
318					if bytes.HasSuffix(fragment, []byte("\n")) {
319						t.Fatalf("fragment %q must not be terminated like a complete record", fragment)
320					}
321					var v interface{}
322					if err := json.Unmarshal(fragment, &v); err == nil {
323						t.Fatalf("fragment %q parses as JSON; it must not be mistaken for a result", fragment)
324					}
325				} else if tc.target == 1 && sink.buf.Len() != 0 {
326					t.Fatalf("first result rejected wholesale but stdout received %q", sink.buf.Bytes())
327				}
328	
329				// 诊断只进入标准错误：唯一一行、固定前缀、带底层原因；
330				// 它是纯文本，不是带 line/index/conflict 的业务 JSON。
331				diagnostic := strings.TrimSuffix(stderr, "\n")
332				if strings.Contains(diagnostic, "\n") {
333					t.Fatalf("want exactly one diagnostic line, stderr = %q", stderr)
334				}
335				wantDiagnostic := "ingest: write error: " + errResultSink.Error()
336				if diagnostic != wantDiagnostic {
337					t.Fatalf("stderr = %q, want %q", stderr, wantDiagnostic)
338				}
339				for _, banned := range []string{`"status"`, `"line"`, `"index"`, `"conflict"`} {
340					if strings.Contains(diagnostic, banned) {
341						t.Fatalf("diagnostic must not be a business JSON record, contains %s: %q",
342							banned, diagnostic)
343					}
344				}
345			})
346		}
347	}
